-- The purge (D83; adjustments V1; T79): what the purge job must never give back (`tombstones`)
-- and its content-free record (`purge_log`). Generated by drizzle-kit, then edited by hand:
-- row-level security on `purge_log` appended (`tombstones` is a system table: codes are unique
-- across all tenants, so the generators check it without a tenant scope). The purge role itself,
-- `restro_purge`, is created by `pnpm db:roles` from src/table-access.ts, which also gives the app
-- role SELECT here and nothing more.
CREATE TABLE "restro"."purge_log" (
	"seq" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "restro"."purge_log_seq_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"tenant_id" text NOT NULL,
	"kind" text NOT NULL,
	"subject_id" text NOT NULL,
	"counts" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "purge_log_kind" CHECK ("restro"."purge_log"."kind" in ('venue', 'menu', 'instance', 'versions', 'tables')),
	CONSTRAINT "purge_log_subject_id" CHECK ("restro"."purge_log"."subject_id" ~ '^[a-z]{2}_[0-9A-Za-z]+$'),
	CONSTRAINT "purge_log_counts_object" CHECK (jsonb_typeof("restro"."purge_log"."counts") = 'object')
);
--> statement-breakpoint
CREATE TABLE "restro"."tombstones" (
	"kind" text NOT NULL,
	"value" text NOT NULL,
	"organization_id" text NOT NULL,
	"purged_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "tombstones_pkey" PRIMARY KEY("kind","value"),
	CONSTRAINT "tombstones_kind" CHECK ("restro"."tombstones"."kind" in ('public_code', 'table_token')),
	CONSTRAINT "tombstones_value_length" CHECK (length("restro"."tombstones"."value") between 1 and 128),
	CONSTRAINT "tombstones_organization_id" CHECK ("restro"."tombstones"."organization_id" ~ '^tn_[0-9A-Za-z]+$')
);
--> statement-breakpoint
